# ! [doc = " IEEE 754-2019 `minimum`."] # ! [doc = ""] # ! [doc = " Per the spec, returns:"] # ! [doc = " - `x` if `x < y`"] # ! [doc = " - `y` if `y < x`"] # ! [doc = " - -0.0 if x and y are zero with opposite signs"] # ! [doc = " - Either `x` or `y` if `x == y` and the signs are the same"] # ! [doc = " - Non-NaN if one operand is NaN"] # ! [doc = " - qNaN if both operands are NaNx"] # ! [doc = ""] # ! [doc = " Excluded from our implementation is sNaN handling."] use split_decls_genesis :: ourprelude :: * ; use crate :: support :: Float ; #[inline] pub fn fminimum_num < F : Float > (x : F , y : F) -> F { let res = if x > y || x . is_nan () { y } else if y > x || y . is_nan () { x } else if x . is_sign_positive () { y } else { x } ; res . canonicalize () }